sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 parallax;
uniform float2 offset;
uniform float evolution;
uniform float scale;
uniform float2 stretch;
uniform float intensity;
uniform float seed;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
uniform float alpha;
uniform float blend;
uniform float bias;
uniform float octaves;
uniform float style;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float vnoise(float3 p) {
    float3 i = floor(p);
    float3 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = mix(hash13(i), hash13(i + float3(1, 0, 0)), f.x);
    float b = mix(hash13(i + float3(0, 1, 0)), hash13(i + float3(1, 1, 0)), f.x);
    float c = mix(hash13(i + float3(0, 0, 1)), hash13(i + float3(1, 0, 1)), f.x);
    float d = mix(hash13(i + float3(0, 1, 1)), hash13(i + float3(1, 1, 1)), f.x);
    return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
float fbm(float3 p, float octaves, float2 drift, float gain) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 9; i++) {
        if (float(i) >= octaves) break;
        sum += amp * vnoise(p);
        norm += amp;
        amp *= gain;
        p = float3(p.xy * 2.03 + drift + float2(17.13, 9.71), p.z * 1.7 + 3.1);
    }
    return sum / max(norm, 0.0001);
}
float3 blendWith(float m, float3 b, float3 s) {
    if (m < 0.5) return s;
    if (m < 1.5) return b * s;
    if (m < 2.5) return b + s - b * s;
    if (m < 3.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, b));
    if (m < 4.5) {
        float3 d = mix(sqrt(b), ((16.0 * b - 12.0) * b + 4.0) * b, step(b, float3(0.25)));
        return mix(b - (1.0 - 2.0 * s) * b * (1.0 - b), b + (2.0 * s - 1.0) * (d - b), step(0.5, s));
    }
    if (m < 5.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, s));
    if (m < 6.5) return min(b + s, 1.0);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return max(b, s);
    if (m < 9.5) return abs(b - s);
    if (m < 10.5) return min(b / max(1.0 - s, 0.0001), 1.0);
    return 1.0 - min((1.0 - b) / max(s, 0.0001), 1.0);
}
float4 permute4(float4 x) {
    x = (x * 34.0 + 1.0) * x;
    return x - floor(x * (1.0 / 289.0)) * 289.0;
}
float snoise(float3 v) {
    float3 i = floor(v + dot(v, float3(1.0 / 3.0)));
    float3 x0 = v - i + dot(i, float3(1.0 / 6.0));
    float3 g = step(x0.yzx, x0.xyz);
    float3 l = 1.0 - g;
    float3 i1 = min(g.xyz, l.zxy);
    float3 i2 = max(g.xyz, l.zxy);
    float3 x1 = x0 - i1 + 1.0 / 6.0;
    float3 x2 = x0 - i2 + 1.0 / 3.0;
    float3 x3 = x0 - 0.5;
    i = i - floor(i * (1.0 / 289.0)) * 289.0;
    float4 p = permute4(permute4(permute4(i.z + float4(0.0, i1.z, i2.z, 1.0)) + i.y + float4(0.0, i1.y, i2.y, 1.0)) + i.x + float4(0.0, i1.x, i2.x, 1.0));
    float n7 = 0.142857142857;
    float4 j = p - 49.0 * floor(p * n7 * n7);
    float4 gx = floor(j * n7);
    float4 gy = floor(j - 7.0 * gx);
    float4 x = gx * (2.0 * n7) + (0.5 * n7 - 1.0);
    float4 y = gy * (2.0 * n7) + (0.5 * n7 - 1.0);
    float4 h = 1.0 - abs(x) - abs(y);
    float4 b0 = float4(x.xy, y.xy);
    float4 b1 = float4(x.zw, y.zw);
    float4 s0 = floor(b0) * 2.0 + 1.0;
    float4 s1 = floor(b1) * 2.0 + 1.0;
    float4 sh = -step(h, float4(0.0));
    float4 a0 = b0.xzyw + s0.xzyw * sh.xxyy;
    float4 a1 = b1.xzyw + s1.xzyw * sh.zzww;
    float3 p0 = float3(a0.xy, h.x);
    float3 p1 = float3(a0.zw, h.y);
    float3 p2 = float3(a1.xy, h.z);
    float3 p3 = float3(a1.zw, h.w);
    float4 norm = 1.79284291400159 - 0.85373472095314 * float4(dot(p0, p0), dot(p1, p1), dot(p2, p2), dot(p3, p3));
    float4 m = max(0.6 - float4(dot(x0, x0), dot(x1, x1), dot(x2, x2), dot(x3, x3)), 0.0);
    m = m * m;
    return 42.0 * dot(m * m, float4(dot(p0, x0) * norm.x, dot(p1, x1) * norm.y, dot(p2, x2) * norm.z, dot(p3, x3) * norm.w));
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float v;
    if (style > 0.5) {
        float2 uv = float2(coord.x - offset.x, size.y - coord.y + offset.y) / size.y;
        float2 p = 0.5 + (uv - 0.5) * max(abs(stretch), float2(0.01)) / max(scale, 0.01);
        float2 drift = float2(-parallax.x, parallax.y) / (size.y * max(scale, 0.01));
        float3 shift = seed * float3(37.1, 17.3, 11.9);
        float amp = 0.5;
        float f = 1.0;
        v = 0.0;
        for (int i = 0; i < 9; i++) {
            if (float(i) >= floor(octaves)) break;
            v += amp * abs(snoise(float3(p * f + drift * float(i), evolution) + shift));
            amp *= 0.5;
            f *= 2.0;
        }
        v = clamp(v * intensity + bias - 0.0086, 0.0, 1.0);
    } else {
        float unit = 0.4 * size.y * max(scale, 0.01);
        float2 p = (coord - size * 0.5 - offset) / (unit * max(abs(stretch), float2(0.01)));
        v = fbm(float3(p + seed * float2(37.1, 17.3), evolution), octaves, parallax / unit, 0.5);
        v = clamp(0.465 + (v - 0.5) * 1.12 * intensity + bias * 0.5, 0.0, 1.0);
    }
    float3 fill = mix(float3(color1.rgb), float3(color2.rgb), v);
    float amount = clamp(alpha, 0.0, 1.0) * mix(float(color1.a), float(color2.a), v);
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = mix(base, clamp(blendWith(blend, base, fill), 0.0, 1.0), amount);
    return half4(half3(rgb) * src.a, src.a);
}
